# Recettes : clins d'œil et easter eggs (mode Infini) — références connues de tous, légendes signalées comme telles
# Cadre validé par le propriétaire ; recherche, contre-vérification indépendante.
RECIPES = [
  # ===================== EXPRESSIONS, FABLES ET CULTURE POPULAIRE =====================
  ("Corde+Pluie", "Déluge"),                          # clin d'œil : « il pleut des cordes » (XVIIe s.) : pluie si drue que les filets d'eau ressemblent à des cordes
  ("Canard+Froid", "Hiver"),                          # clin d'œil : « un froid de canard » (XIXe s.) : le grand froid de la chasse aux canards, d'automne en hiver
  ("Chat+Langage", "Rhume"),                          # clin d'œil : « avoir un chat dans la gorge » : voix enrouée ; vient de « maton » (grumeau) confondu avec « matou »
  ("Cœur+Éclair", "Amour"),                           # clin d'œil : « le coup de foudre » : amour soudain, au premier regard (sens amoureux depuis la fin du XVIIIe s.)
  ("Pluie+Poule", "Peur"),                            # clin d'œil : « être une poule mouillée » (Richelet, 1680) : la poule trempée par la pluie a l'air misérable et craintive
  ("Mathématiques+Mouton", "Sommeil"),                # clin d'œil : « compter les moutons » pour s'endormir (astuce populaire ; une étude de l'université d'Oxford la trouve peu efficace)
  ("Cafard+Humain", "Tristesse"),                     # clin d'œil : « avoir le cafard » : être triste, sens popularisé par Baudelaire (Les Fleurs du mal)
  ("Baleine+Joie", "Rire"),                           # clin d'œil : « rire comme une baleine » (XIXe s.) : rire la bouche grande ouverte (origine discutée)
  ("Chat+Chien", "Colère"),                           # clin d'œil : « s'entendre comme chien et chat » (XVIe s.) : se disputer sans cesse
  ("Corbeau+Renard", "Fromage"),                      # clin d'œil : La Fontaine, Le Corbeau et le Renard : le corbeau ouvre le bec, « laisse tomber sa proie »
  ("Or+Poule", "Œuf"),                                # clin d'œil : La Fontaine, La Poule aux œufs d'or : la poule qui « pondait tous les jours un œuf d'or » (fable)
  ("Insecte+Été", "Cigale"),                          # clin d'œil : La Cigale et la Fourmi « ayant chanté tout l'été » ; en vrai, la cigale chante l'été dans le Midi
  ("Cigale+Fourmi", "Danse"),                         # clin d'œil : La Fontaine : « Vous chantiez ? j'en suis fort aise. Eh bien ! dansez maintenant. » (en vrai, la cigale meurt avant l'hiver)
  ("Épée+Pierre", "Roi"),                             # clin d'œil : l'épée dans le rocher (Robert de Boron, vers 1200) : seul le vrai roi, Arthur, peut la retirer (légende)
  ("Pomme+Pomme+Pomme", "Enfant"),                    # clin d'œil : « haut comme trois pommes » (début XXe s.) : se dit d'un tout petit enfant
  ("Air+Grenouille+Vache", "Explosion"),              # clin d'œil : La Fontaine, La Grenouille qui se veut faire aussi grosse que le Bœuf : « s'enfla si bien qu'elle creva »
  ("Électricité+Laboratoire+Mort", "Monstre de Frankenstein"),  # clin d'œil : Mary Shelley, Frankenstein (1818) : le savant Victor Frankenstein ranime un corps ; l'électricité, suggérée par le galvanisme, est montrée surtout au cinéma
  ("Arc+Forêt+Monnaie", "Robin des Bois"),            # clin d'œil : Robin des Bois, l'archer hors-la-loi de la forêt de Sherwood qui prend aux riches pour donner aux pauvres (légende, ballades du XIVe-XVe s.)
  # ===================== SCIENCES ET MYTHES =====================
  ("Champignon+Laboratoire", "Antibiotique"),         # clin d'œil : Fleming, 1928 — fait : au retour de vacances, une moisissure (Penicillium) a envahi une boîte de culture oubliée de son labo et tué les bactéries autour d'elle ; c'est la pénicilline
  ("Maladie+Vache", "Vaccin"),                        # clin d'œil : Jenner, 1796 — fait : il protège de la variole avec la « variole de la vache » ; « vaccin » vient du latin vacca, la vache
  ("Chien+Cloche", "Faim"),                           # clin d'œil : le chien de Pavlov — fait : le chien salive au signal qui annonce la nourriture ; la cloche elle-même est surtout une légende (Pavlov utilisait plutôt un métronome ou une sonnerie) (légende)
  ("Lune+Télescope", "Cratère"),                      # clin d'œil : Galilée, 1609-1610 — fait : sa lunette lui montre que la Lune n'est pas lisse mais couverte de montagnes et de cratères (Sidereus Nuncius)
  ("Chat+Physique quantique", "Zombie"),              # clin d'œil : le chat de Schrödinger, « à la fois mort et vivant » — fait : c'est une expérience de pensée de 1935, jamais réalisée sur un vrai chat ; le zombie est la blague du « mort-vivant »
  ("Armée+Pomme de terre", "Potager"),                # clin d'œil : Parmentier fait garder ses champs de pommes de terre par des soldats le jour seulement, pour que les Parisiens viennent en voler la nuit et les plantent chez eux (légende, apparue après sa mort en 1814) ; fait : il a bien promu la pomme de terre et cultivé la plaine des Sablons en 1786
  ("Cire+Plume", "Ailes d'Icare"),                    # clin d'œil : Icare — mythe : Dédale fabrique des ailes de plumes tenues par du lin et de la cire pour s'évader avec son fils (Ovide, Métamorphoses VIII) (légende)
  ("Ailes d'Icare+Soleil", "Mer"),                    # clin d'œil : Icare vole trop près du Soleil, la cire fond et il tombe dans la mer qui porte son nom, la mer Icarienne (légende) ; fait : cette mer existe bien, près de l'île d'Icarie
  ("Cheval de Troie+Ville", "Ruine"),                 # clin d'œil : le cheval de Troie — mythe : les Grecs cachés dans le cheval ouvrent les portes et Troie est détruite (Virgile, Énéide II) (légende)
  ("Feu+Hydre", "Héros"),                             # clin d'œil : Hercule et l'Hydre de Lerne — mythe : chaque tête coupée repousse, alors Iolaos brûle les cous avec une torche (Apollodore) (légende)
  ("Arbre+Humain+Pomme", "Gravité"),                  # clin d'œil : la pomme de Newton — fait : Newton a raconté à Stukeley (1726) que la chute d'une pomme, vue alors qu'il songeait, lui a inspiré la gravitation ; la pomme tombée sur sa tête est une légende ajoutée plus tard (légende)
  ("Eau+Masse+Pensée", "Idée"),                       # clin d'œil : « Eurêka ! » d'Archimède dans son bain (légende) — récit de Vitruve, 200 ans après : l'eau qui déborde lui donne l'idée de mesurer le volume de la couronne du roi ; fait : le principe d'Archimède sur les corps plongés dans l'eau est bien de lui
  ("Cerf-volant+Clé+Orage", "Électricité statique"),  # clin d'œil : Franklin, 1752 (légende en partie) — récit de Franklin et Priestley (1767), sans témoin, certains historiens doutent qu'elle ait eu lieu ; si elle a eu lieu, la foudre n'a pas frappé le cerf-volant : les charges du nuage descendent le fil mouillé jusqu'à la clé, d'où jaillissent des étincelles
  ("Enfant+Enfant+Loup", "Empire romain"),            # clin d'œil : Romulus et Rémus, jumeaux nourris par une louve, fondent la ville de Rome en 753 av. J.-C. (légende) ; fait : Rome ne devient un empire qu'en 27 av. J.-C., et la louve est son symbole depuis l'Antiquité
  ("Or+Pain+Roi", "Faim"),                            # clin d'œil : le roi Midas — mythe : tout ce qu'il touche devient or, même son pain, et il ne peut plus manger (Ovide, Métamorphoses XI) (légende)
  ("Bois+Cheval+Guerre", "Cheval de Troie"),          # clin d'œil : le cheval de Troie — mythe : après dix ans de guerre, les Grecs construisent un grand cheval de bois et s'y cachent ; il est cité dans l'Odyssée et raconté dans l'Énéide, pas dans l'Iliade (légende)
  ("Dieu+Maladie+Poterie", "Boîte de Pandore"),       # clin d'œil : la boîte de Pandore — mythe : les dieux confient à Pandore un récipient plein des maux du monde, maladies comprises (Hésiode) (légende) ; fait : chez Hésiode c'est une jarre (pithos), le mot « boîte » vient d'une erreur de traduction d'Érasme en 1508
  ("Colline+Humain+Mouvement+Pierre", "Fatigue"),     # clin d'œil : Sisyphe — mythe : il pousse sans fin un rocher en haut d'une colline, qui redescend à chaque fois (Odyssée XI) (légende) ; d'où un « travail de Sisyphe »
]
